function solve(s) {
  const out = [];
  function dfs(i, parts) {
    if (parts.length === 4) {
      if (i === s.length) out.push(parts.join('.'));
      return;
    }
    if (s.length - i > (4 - parts.length) * 3) return;
    let num = 0;
    for (let j = i; j < s.length && j < i + 3; j++) {
      num = num * 10 + (s.charCodeAt(j) - 48);
      if (num > 255) break;
      parts.push(s.slice(i, j + 1));
      dfs(j + 1, parts);
      parts.pop();
      if (num === 0) break;
    }
  }
  dfs(0, []);
  return out;
}
